import { defineSchema } from "convex/server";

const runId = (process.env.ZEALT_RUN_ID as string).replace(/-/g, "_");

export default defineSchema({
  [`users_${runId}`]: {
    name: "string",
    role: "string",
  },
  [`documents_${runId}`]: {
    title: "string",
    content: "string",
    authorId: "id",
  },
});

import { mutation } from "../_generated/server";

const runId = (process.env.ZEALT_RUN_ID as string).replace(/-/g, "_");

export default mutation({
  args: {},
  handler: async (ctx) => {
    const adminId = await ctx.db.insert(`users_${runId}`, {
      name: "Admin",
      role: "admin",
    });

    const editorId = await ctx.db.insert(`users_${runId}`, {
      name: "Editor",
      role: "editor",
    });

    const viewerId = await ctx.db.insert(`users_${runId}`, {
      name: "Viewer",
      role: "viewer",
    });

    return { adminId, editorId, viewerId };
  },
});

import { query, mutation } from "./_generated/server";
import { ConvexError } from "convex/values";

const runId = (process.env.ZEALT_RUN_ID as string).replace(/-/g, "_");

export const get = query({
  args: { userId: "string" },
  handler: async (ctx, args) => {
    const documents = await ctx.db.query(`documents_${runId}`).collect();
    return documents;
  },
});

export const create = mutation({
  args: { userId: "string", title: "string", content: "string" },
  handler: async (ctx, args) => {
    const user = await ctx.db.get(args.userId as any);
    if (!user || (user.role !== "admin" && user.role !== "editor")) {
      throw new ConvexError("Unauthorized");
    }

    const documentId = await ctx.db.insert(`documents_${runId}`, {
      title: args.title,
      content: args.content,
      authorId: args.userId as any,
    });

    return documentId;
  },
});

export const delete = mutation({
  args: { userId: "string", documentId: "string" },
  handler: async (ctx, args) => {
    const user = await ctx.db.get(args.userId as any);
    if (!user || user.role !== "admin") {
      throw new ConvexError("Unauthorized");
    }

    await ctx.db.delete(args.documentId as any);
  },
});

